// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const num = (v, fallback) => (text(v) !== '' && Number.isFinite(Number(v)) ? Number(v) : fallback);
const flag = (v) => v === true || lower(v) === 'true';
const isEmail = (v) => /^[^\s@<>"',;]+@[^\s@<>"',;]+\.[^\s@<>"',;]+$/.test(text(v));
// ---- End of helpers ----

const cfg = $('Set Configuration Settings').first().json;
const problems = [];
const unset = (v) => !isEmail(v) || /@example\.com$/i.test(text(v));

if (!text(cfg.googleSheetId) || cfg.googleSheetId === 'YOUR_GOOGLE_SHEET_ID') {
  problems.push('googleSheetId: the part of your sheet URL between /d/ and /edit');
}
if (unset(cfg.staffEmail)) problems.push('staffEmail: your own address (in test mode every email goes here)');
if (unset(cfg.replyToEmail)) problems.push('replyToEmail: the address clients should reply to');
if (!/^https?:\/\//i.test(text(cfg.bookingPageUrl)) || /example\.com/i.test(text(cfg.bookingPageUrl))) {
  problems.push('bookingPageUrl: the page where clients book');
}
if (!text(cfg.businessName) || cfg.businessName === 'Your Business Name') problems.push('businessName');
// The stop alert reads staffEmail without running this node, so it has to be plain text.
const typed = (($('Set Configuration Settings').params.assignments || {}).assignments || []).find((a) => a.name === 'staffEmail');
if (typed && String(typed.value).startsWith('=')) problems.push('staffEmail: type the address as plain text, not an expression');

for (const k of ['firstReminderDays', 'secondReminderDays', 'finalReminderDays']) {
  if (!Number.isInteger(Number(cfg[k])) || Number(cfg[k]) < 0) problems.push(`${k}: a whole number of days`);
}
if (!(Number(cfg.maxRemindersPerRun) >= 1)) problems.push('maxRemindersPerRun: at least 1');
if (problems.length) {
  throw new Error(`Nothing was sent. Fill in Set Configuration Settings:\n- ${problems.join('\n- ')}`);
}
return [{ json: { timezone: $now.zoneName } }];

// Google Sheets silently ignores values for columns it cannot find, so a typo in a header
// would lose the record of what was sent and cause repeat emails. Check before sending anything.
const REQUIRED = {"Bookings": ["Booking ID", "Client Name", "Client Email", "Service", "Appointment Date", "Appointment Time", "Status", "Past No Shows", "Reminders Sent", "Last Reminder At", "Last Reminder Error"]};
const ranges = $input.first().json.valueRanges || [];
const problems = [];
for (const [tab, columns] of Object.entries(REQUIRED)) {
  const found = ranges.find((r) => String(r.range || '').replace(/'/g, '').startsWith(`${tab}!`));
  const headers = ((found && found.values && found.values[0]) || []).map((h) => String(h));
  for (const col of columns) {
    if (headers.includes(col)) continue;
    const near = headers.find((h) => h.trim().toLowerCase() === col.toLowerCase());
    problems.push(near !== undefined
      ? `${tab}: header "${near}" must be exactly "${col}"`
      : `${tab}: column "${col}" is missing`);
  }
}
if (problems.length) {
  throw new Error(`Nothing was sent. Fix row 1 of your sheet:\n- ${problems.join('\n- ')}`);
}
return [{ json: {} }];

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const num = (v, fallback) => (text(v) !== '' && Number.isFinite(Number(v)) ? Number(v) : fallback);
const flag = (v) => v === true || lower(v) === 'true';
const isEmail = (v) => /^[^\s@<>"',;]+@[^\s@<>"',;]+\.[^\s@<>"',;]+$/.test(text(v));
const list = (v) => text(v).split(',').map((x) => x.trim()).filter(Boolean);
// IDs are matched exactly as Google Sheets displays them. When results are written back, the Sheets
// update looks the row up by its displayed text, so this is the value that finds the row again
// (a number formatted as 1,001.00 is read as 1001 but found as "1,001.00").
const DISPLAYED = {};
for (const r of $('Fetch Google Sheets Data').first().json.valueRanges || []) {
  DISPLAYED[String(r.range || '').replace(/'/g, '').split('!')[0]] = r.values || [];
}
// Returns null when the row moved between the two reads (sorted, inserted or deleted in between):
// a text cell shows exactly the same text in both reads, so any difference means it is not the same row.
// Such a row is left for the next run instead of risking a write to someone else's row.
const shownKey = (tab, column, row) => {
  const values = DISPLAYED[tab] || [];
  const headers = values[0] || [];
  const line = values[(row.row_number || 0) - 1];
  if (!line) return null;
  for (const [col, v] of Object.entries(row)) {
    if (typeof v !== 'string' || v === '') continue;
    const at = headers.indexOf(col);
    if (at >= 0 && line[at] !== v) return null;
  }
  const idx = headers.indexOf(column);
  return idx >= 0 && line[idx] !== undefined && line[idx] !== null ? String(line[idx]) : '';
};
// Values written back unchanged keep their original type, so a test run or an undo changes nothing.
const raw = (v) => (v === undefined || v === null ? '' : v);
const MS_PER_DAY = 86400000;
const SHEETS_EPOCH = 25569; // Google Sheets serial number of 1970-01-01

// Returns { y, m, d } or null. Accepts Google Sheets serial numbers and YYYY-MM-DD.
// Ambiguous text such as 03/04/2026 is rejected, never guessed.
function parseDate(v) {
  if (typeof v === 'number' && Number.isFinite(v)) {
    const dt = new Date(Math.round((v - SHEETS_EPOCH) * MS_PER_DAY));
    return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
  }
  const s = text(v);
  if (!s) return null;
  if (/^\d+(\.\d+)?$/.test(s)) return parseDate(Number(s));
  const m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})(?=$|[T\s])/);
  if (!m) return null;
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  const check = new Date(Date.UTC(y, mo - 1, d));
  if (check.getUTCMonth() !== mo - 1 || check.getUTCDate() !== d) return null;
  return { y, m: mo, d };
}

// Returns minutes after midnight or null. Accepts 14:30, 2:30 PM and Sheets time values.
function parseTime(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return Math.round((v - Math.floor(v)) * 1440) % 1440;
  const m = lower(v).match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(am|pm)?$/);
  if (!m) return null;
  let h = Number(m[1]);
  const min = Number(m[2]);
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  return h > 23 || min > 59 ? null : h * 60 + min;
}

const dayNumber = (p) => Math.round(Date.UTC(p.y, p.m - 1, p.d) / MS_PER_DAY);
const pad = (n) => String(n).padStart(2, '0');
const formatDate = (p) => `${p.y}-${pad(p.m)}-${pad(p.d)}`;
const formatTime = (mins) => (mins === null ? '' : `${pad(Math.floor(mins / 60))}:${pad(mins % 60)}`);

// "Today" and "now" come from $now, which follows Workflow settings > Timezone.
// Nothing here depends on the timezone of the server running n8n.
const todayNumber = () => dayNumber({ y: $now.year, m: $now.month, d: $now.day });
const nowMinutes = () => todayNumber() * 1440 + $now.hour * 60 + $now.minute;
// ---- End of helpers ----

const cfg = $('Set Configuration Settings').first().json;
const stages = [
  { tag: 'first', days: Number(cfg.firstReminderDays) },
  { tag: 'second', days: Number(cfg.secondReminderDays) },
  { tag: 'final', days: Number(cfg.finalReminderDays) },
].sort((a, b) => b.days - a.days); // furthest from the appointment first

const cap = Math.max(1, num(cfg.maxRemindersPerRun, 200));
const highRisk = num(cfg.highRiskNoShowCount, 1);
const today = todayNumber();
const rows = $input.all();

// A Booking ID used twice would update the wrong row, so duplicated IDs are skipped (and reported).
const idCount = {};
for (const r of rows) {
  const k = shownKey('Bookings', 'Booking ID', r.json);
  if (text(k)) idCount[k] = (idCount[k] || 0) + 1;
}

const due = [];
rows.forEach((item, index) => {
  const row = item.json;
  if (lower(row['Status']) !== 'confirmed') return;
  const key = shownKey('Bookings', 'Booking ID', row);
  const date = parseDate(row['Appointment Date']);
  // Rows that cannot be read reliably are listed by "Identify Incomplete Booking Rows" instead.
  if (!text(key) || idCount[key] > 1 || !date || !isEmail(row['Client Email'])) return;

  const daysUntil = dayNumber(date) - today;
  if (daysUntil < 0) return;
  const time = parseTime(row['Appointment Time']);
  if (daysUntil === 0 && time !== null && time <= $now.hour * 60 + $now.minute) return; // already started

  // Every stage whose window has opened; the last one is the closest to the appointment.
  const reached = stages.filter((s) => daysUntil <= s.days);
  if (reached.length === 0) return;
  const current = reached[reached.length - 1];
  const alreadySent = list(row['Reminders Sent']);
  if (alreadySent.includes(current.tag)) return;

  // Earlier stages missed while the workflow was off are marked done, never sent late.
  const after = [...new Set([...alreadySent, ...reached.map((s) => s.tag)])];
  const pastNoShows = num(row['Past No Shows'], 0);

  due.push({
    json: {
      bookingKey: key,
      clientName: text(row['Client Name']) || 'there',
      clientEmail: text(row['Client Email']),
      service: text(row['Service']) || 'appointment',
      appointmentDate: formatDate(date),
      appointmentTime: formatTime(time),
      daysUntil,
      stage: current.tag,
      isHighRisk: pastNoShows >= highRisk,
      before: {
        remindersSent: raw(row['Reminders Sent']),
        lastReminderAt: raw(row['Last Reminder At']),
        error: raw(row['Last Reminder Error']),
      },
      remindersSentAfter: after.join(','),
    },
    pairedItem: { item: index },
  });
});

// Soonest first, so if the cap is reached it is the furthest appointments that wait a day.
due.sort((a, b) => a.json.daysUntil - b.json.daysUntil);
const selected = due.slice(0, cap);
for (const item of selected) item.json.dueTotal = due.length;
return selected;

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const num = (v, fallback) => (text(v) !== '' && Number.isFinite(Number(v)) ? Number(v) : fallback);
const flag = (v) => v === true || lower(v) === 'true';
// ---- End of helpers ----

const cfg = $('Set Configuration Settings').first().json;
const b = $json;
const when = b.appointmentTime ? `${b.appointmentDate} at ${b.appointmentTime}` : b.appointmentDate;
const relative = b.daysUntil === 0 ? 'today' : b.daysUntil === 1 ? 'tomorrow' : `in ${b.daysUntil} days`;

let subject;
let lines;
if (b.isHighRisk) {
  // Clients with a past no-show are asked to confirm. Replies arrive in your inbox.
  subject = `Please confirm your ${b.service} appointment ${relative}`;
  lines = [
    `Hi ${b.clientName},`, '',
    `Your ${b.service} appointment is ${relative}: ${when}.`, '',
    'Could you reply to this email to confirm you can make it?',
    'If we do not hear from you, someone from our team may call to check.', '',
    `Need a different time? You can rebook here: ${cfg.bookingPageUrl}`, '',
    'Thank you,', cfg.businessName,
  ];
} else {
  subject = `Reminder: your ${b.service} appointment ${relative}`;
  lines = [
    `Hi ${b.clientName},`, '',
    `This is a reminder that your ${b.service} appointment is ${relative}.`, '',
    `When: ${when}`, '',
    `Need to reschedule? You can do it here: ${cfg.bookingPageUrl}`, '',
    'See you soon,', cfg.businessName,
  ];
}

const testMode = flag(cfg.testMode);
// What "Update Reminder Status in Sheets" writes before the email goes out. Test runs write the old values back.
const claim = testMode ? b.before : { remindersSent: b.remindersSentAfter, lastReminderAt: $now.toISO(), error: 'Sending - not confirmed yet' };
return {
  json: {
    ...b,
    testMode,
    claim,
    to: testMode ? cfg.staffEmail : b.clientEmail,
    subject: testMode ? `[TEST for ${b.clientEmail}] ${subject}` : subject,
    body: lines.join('\n'),
  },
};

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
// ---- End of helpers ----

// The Gmail node only returns { id, threadId, labelIds } or { error }.
// Everything else is read from the email this result belongs to (paired item).
const email = $('Prepare Reminder Email').item.json;
const delivered = Boolean($json.id) && !$json.error;
const error = delivered ? '' : text($json.error) || 'Gmail did not return a message id';
// Test runs never change the sheet. A live run confirms a delivered email or undoes a failed one.
const live = !email.testMode;

// Delivered: keep what was claimed and clear the "sending" mark. Failed: put the row back as it was.
const final = !live ? email.before : delivered ? { ...email.claim, error: '' } : { ...email.before, error };
return { json: { ...email, delivered, error, final } };

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
// ---- End of helpers ----

const cfg = $('Set Configuration Settings').first().json;
const rows = $('Log Reminder Send Result').all().map((i) => i.json);
const sent = rows.filter((r) => r.delivered);
const failed = rows.filter((r) => !r.delivered);
const testMode = rows.some((r) => r.testMode);
const line = (r) => `- ${r.appointmentDate}${r.appointmentTime ? ' ' + r.appointmentTime : ''} | ${r.clientName} | ${r.service} | ${r.stage} reminder`;

const parts = [];
if (testMode) {
  parts.push('TEST MODE IS ON: every email below went to you, not to clients, and the sheet was not changed.');
  parts.push('Turn testMode off in Set Configuration Settings when you are ready.', '');
}
parts.push(`Sent: ${sent.length}   Failed: ${failed.length}`);

const dueTotal = rows.length ? rows[0].dueTotal : 0;
if (dueTotal > rows.length) parts.push(`Held back by maxRemindersPerRun (will go tomorrow): ${dueTotal - rows.length}`);
if (failed.length) parts.push('Not-delivered reminders are tried again on the next run.');
const call = sent.filter((r) => r.isHighRisk);
if (call.length) {
  parts.push('', 'Asked to confirm because of a past no-show - worth a call if they do not reply:');
  for (const r of call) parts.push(line(r));
}
if (failed.length) {
  parts.push('', 'NOT DELIVERED:');
  for (const r of failed) parts.push(`${line(r)} | ${r.error}`);
}
if (sent.length) {
  parts.push('', 'Delivered:');
  for (const r of sent) parts.push(line(r));
}
parts.push('', `Dates and times use the workflow timezone (${$now.zoneName}). Change it under Workflow settings if this is wrong.`);

const prefix = (testMode ? '[TEST] ' : '') + (failed.length ? 'ACTION NEEDED: ' : '');
return [{
  json: {
    to: cfg.staffEmail,
    subject: `${prefix}${sent.length} reminders sent, ${failed.length} not delivered`,
    body: parts.join('\n'),
  },
}];

// ---- Shared helpers ----
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const isEmail = (v) => /^[^\s@<>"',;]+@[^\s@<>"',;]+\.[^\s@<>"',;]+$/.test(text(v));
// IDs are matched exactly as Google Sheets displays them. When results are written back, the Sheets
// update looks the row up by its displayed text, so this is the value that finds the row again
// (a number formatted as 1,001.00 is read as 1001 but found as "1,001.00").
