  if (/^\d+(\.\d+)?$/.test(s)) return parseDate(Number(s));
  const m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})(?=$|[T\s])/);
  if (!m) return null;
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  const check = new Date(Date.UTC(y, mo - 1, d));
  if (check.getUTCMonth() !== mo - 1 || check.getUTCDate() !== d) return null;
  return { y, m: mo, d };
}

// Returns minutes after midnight or null. Accepts 14:30, 2:30 PM and Sheets time values.
function parseTime(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return Math.round((v - Math.floor(v)) * 1440) % 1440;
  const m = lower(v).match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(am|pm)?$/);
  if (!m) return null;
  let h = Number(m[1]);
  const min = Number(m[2]);
  if (m[3] === 'pm' && h < 12) h += 12;
  if (m[3] === 'am' && h === 12) h = 0;
  return h > 23 || min > 59 ? null : h * 60 + min;
}

const dayNumber = (p) => Math.round(Date.UTC(p.y, p.m - 1, p.d) / MS_PER_DAY);
const pad = (n) => String(n).padStart(2, '0');
const formatDate = (p) => `${p.y}-${pad(p.m)}-${pad(p.d)}`;
const formatTime = (mins) => (mins === null ? '' : `${pad(Math.floor(mins / 60))}:${pad(mins % 60)}`);

// "Today" and "now" come from $now, which follows Workflow settings > Timezone.
// Nothing here depends on the timezone of the server running n8n.
const todayNumber = () => dayNumber({ y: $now.year, m: $now.month, d: $now.day });
const nowMinutes = () => todayNumber() * 1440 + $now.hour * 60 + $now.minute;
// ---- End of helpers ----

const cfg = $('Set Configuration Settings').first().json;
const today = todayNumber();
const rows = $input.all();
const rowNo = (item, index) => item.json.row_number ?? index + 2;
const idRows = {};
rows.forEach((item, index) => {
  const k = shownKey('Bookings', 'Booking ID', item.json);
  if (text(k)) (idRows[k] = idRows[k] || []).push(rowNo(item, index));
});

const problems = [];
rows.forEach((item, index) => {
  const row = item.json;
  if (text(row['Last Reminder Error']) === 'Sending - not confirmed yet') {
    problems.push(`- Row ${rowNo(item, index)}: a reminder was being sent but the result was never recorded. ` +
      'Check your Gmail Sent folder, then clear Last Reminder Error. That reminder will not be sent again on its own.');
  }
  if (lower(row['Status']) !== 'confirmed') return;
  const date = parseDate(row['Appointment Date']);
  if (date && dayNumber(date) < today) return; // past bookings no longer matter

  const issues = [];
  const k = shownKey('Bookings', 'Booking ID', row);
  if (k === null) return; // moved during this run, checked again next run
  if (!text(k)) issues.push('Booking ID is empty');
  else if (idRows[k].length > 1) issues.push(`Booking ID "${k}" is used on rows ${idRows[k].join(', ')}`);
  if (!date) issues.push(`Appointment Date "${text(row['Appointment Date'])}" is not a date (use YYYY-MM-DD)`);
  if (!isEmail(row['Client Email'])) issues.push(`Client Email "${text(row['Client Email'])}" is not a valid address`);
  if (text(row['Appointment Time']) && parseTime(row['Appointment Time']) === null) {
    issues.push(`Appointment Time "${text(row['Appointment Time'])}" is not a time (use 14:30)`);
  }
  if (issues.length) problems.push(`- Row ${rowNo(item, index)}: ${issues.join('; ')}`);
});

if (problems.length === 0) return [];
return [{
  json: {
    to: cfg.staffEmail,
    subject: `${problems.length} booking rows need your attention`,
    body: ['Nothing is guessed: these rows are skipped until they are fixed.', '', ...problems].join('\n'),
  },
}];

// Runs in a separate execution started by the Error Trigger, where Set Configuration Settings has not run.
// The .params of a node returns its configured values without running it.
const assignments = ($('Set Configuration Settings').params.assignments || {}).assignments || [];
const setting = (name) => String((assignments.find((a) => a.name === name) || {}).value ?? '').trim();
const to = setting('staffEmail');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to) || /@example\.com$/i.test(to)) return []; // no real address to alert yet

const e = $input.first().json;
const execution = e.execution || {};
const name = (e.workflow && e.workflow.name) || 'n8n workflow';
const message = (execution.error && execution.error.message) || (e.trigger && e.trigger.error && e.trigger.error.message) || 'unknown';
// Manual runs never start this branch, so mode "manual" can only be the editor's sample data.
if (execution.mode === 'manual' || message === 'Example Error Message') return [];

// The same failure is reported at most once every 6 hours, so a workflow that keeps failing
// every 15 minutes does not flood the inbox.
const memory = $getWorkflowStaticData('global');
const key = `${execution.lastNodeExecuted || ''}|${message}`;
const nowMs = Date.now();
memory.failureAlerts = memory.failureAlerts || {};
for (const [k, at] of Object.entries(memory.failureAlerts)) if (nowMs - at > 6 * 3600000) delete memory.failureAlerts[k];
if (memory.failureAlerts[key]) return [];
memory.failureAlerts[key] = nowMs;
const lines = [
  `"${name}" stopped before it finished.`,
  '',
  `Step: ${execution.lastNodeExecuted || 'unknown'}`,
  `Error: ${message}`,
];
if (execution.url) lines.push(`Details: ${execution.url}`);
lines.push('',
  'Emails sent before this step are not sent again. If it stopped while recording results, some rows',
  'may show "Sending - not confirmed yet": check your Gmail Sent folder for those clients.',
  'The same failure is reported at most once every 6 hours. Fix it and the next run carries on.');
return [{ json: { to, subject: `Workflow stopped: ${name}`, body: lines.join('\n') } }];
